import sys

def is_stable(sublist):
    sx = set()
    for string in sublist:
        for i in range(len(string)):
            sx.add(string[i:] + string[:i])

    for length in range(1, len(sublist) + 1):
        for start in range(len(sublist) - length + 1):
            message = ''.join(sublist[start:start+length])
            count = 0
            for i in range(len(message)):
                if message[i:] + message[:i] in sx:
                    count += 1
            if count != length:
                return False
    return True

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    A = input[1:]
    result = 0

    for start in range(n):
        for end in range(start + 1, n + 1):
            if is_stable(A[start:end]):
                result += 1

    print(result)

if __name__ == "__main__":
    main()
